'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const motionMedia=matchMedia('(prefers-reduced-motion: reduce)');let reduce=motionMedia.matches;try{const saved=localStorage.getItem('ad-motion');if(saved!==null)reduce=saved==='reduced'}catch{}
function setMotion(){document.documentElement.classList.toggle('no-motion',reduce);$('#motion-toggle').setAttribute('aria-pressed',String(reduce));$('#motion-toggle').textContent=reduce?'Movimiento: reducido':'Movimiento: activado';if(reduce)resetHero()}
