const menu=$('.menu');function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menú');$('#navigation').classList.remove('open')}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');$('#navigation').classList.toggle('open',open)});$$('#navigation a').forEach(a=>a.addEventListener('click',closeMenu));addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
const heroArea=$('#hero-art-area');function resetHero(){['--mx','--my'].forEach(k=>heroArea.style.setProperty(k,'0px'));['--rx','--ry'].forEach(k=>heroArea.style.setProperty(k,'0deg'))}
let heroFrame=0;heroArea.addEventListener('pointermove',e=>{if(reduce||!matchMedia('(pointer:fine)').matches)return;cancelAnimationFrame(heroFrame);heroFrame=requestAnimationFrame(()=>{const r=heroArea.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;heroArea.style.setProperty('--mx',x*15+'px');heroArea.style.setProperty('--my',y*12+'px');heroArea.style.setProperty('--rx',-y*6+'deg');heroArea.style.setProperty('--ry',x*6+'deg')})});heroArea.addEventListener('pointerleave',resetHero);setMotion();
const artwork={volume:{src:'fusion-master.webp',caption:'01 / DE LA IDEA A LA DIMENSIÓN',alt:'Composición original de papel cian y magenta, vidrio ámbar, pigmentos y trazos de construcción fusionados en una escultura gráfica'},matter:{src:'fusion-matter.webp',caption:'02 / COLOR, MATERIA Y POSIBILIDAD',alt:'Cintas de acrílico transparente, pigmentos cian y magenta y papel amarillo fusionados en una composición original'},expression:{src:'fusion-expression.webp',caption:'03 / UN GESTO CAMBIA EL CONCEPTO',alt:'Escultura gráfica original de cintas, papel impreso, pigmentos, latón y un trazo de lápiz'}};
let artTimer;$$('[data-art]').forEach(b=>b.addEventListener('click',()=>{const a=artwork[b.dataset.art];$$('[data-art]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const image=$('#hero-sculpture');clearTimeout(artTimer);image.classList.add('changing');artTimer=setTimeout(()=>{image.src='assets/'+a.src;image.alt=a.alt;$('#art-caption').textContent=a.caption;image.classList.remove('changing')},reduce?0:160)}));
const serviceDetails=$$('.service-list details');serviceDetails.forEach(d=>{d.style.setProperty('--service-color',d.dataset.color);d.addEventListener('toggle',()=>{if(!d.open)return;serviceDetails.forEach(x=>{if(x!==d)x.open=false});$('#service-symbol').textContent=d.dataset.symbol;$('#service-art-name').textContent=d.dataset.name;$('.service-stage').style.setProperty('--service-color',d.dataset.color)})});$$('[data-service]').forEach(a=>a.addEventListener('click',()=>{$('#service').value=a.dataset.service;clearBrief()}));
// The creative desk renders original compositions, driven entirely by visitor controls.
const canvas=$('#design-canvas'),ctx=canvas.getContext('2d');canvas.tabIndex=0;canvas.setAttribute('aria-describedby','design-status');
const palettes={cmyk:{name:'CMYK',a:'#00d9ec',b:'#f83e98',c:'#ffe145',hue:0},fire:{name:'Fuego',a:'#ff7345',b:'#ea3b70',c:'#ffc148',hue:310},violet:{name:'Ultravioleta',a:'#a692ff',b:'#f05caf',c:'#5cd3ef',hue:34}};
const design={palette:'cmyk',composition:'sculpture',energy:60,word:'IMAGINÁ',seed:7,spark:{x:.78,y:.25}};const images={};
const imageLoads=['fusion-master.webp','fusion-expression.webp','fusion-matter.webp','archive-fusion.webp'].map(src=>new Promise(resolve=>{const im=new Image();im.onload=()=>{images[src]=im;resolve()};im.onerror=resolve;im.src='assets/'+src}));
function rng(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function line(x1,y1,x2,y2,color,width=1){ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function smallText(text,x,y,color,size=13,align='left'){ctx.font=size+'px Technical, monospace';ctx.fillStyle=color;ctx.textAlign=align;ctx.fillText(text,x,y)}
function spark(x,y,r,color){ctx.save();ctx.translate(x,y);ctx.rotate(Math.PI/8);ctx.strokeStyle=color;ctx.lineWidth=6;for(let i=0;i<8;i++){ctx.rotate(Math.PI/4);ctx.beginPath();ctx.moveTo(0,-r*.3);ctx.lineTo(0,-r);ctx.stroke()}ctx.beginPath();ctx.arc(0,0,r*.14,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.restore()}
function fitWord(word,maxWidth,start){let size=start;ctx.font='700 '+size+'px Display, sans-serif';while(size>38&&ctx.measureText(word).width>maxWidth){size-=2;ctx.font='700 '+size+'px Display, sans-serif'}return size}
function draw(){const p=palettes[design.palette],w=canvas.width,h=canvas.height,rand=rng(design.seed);ctx.clearRect(0,0,w,h);ctx.fillStyle='#090b13';ctx.fillRect(0,0,w,h);let glow=ctx.createRadialGradient(650,360,30,450,550,820);glow.addColorStop(0,p.b+'22');glow.addColorStop(.55,p.a+'12');glow.addColorStop(1,'#090b13');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);const archive=images['archive-fusion.webp'];if(archive){ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=.23;ctx.drawImage(archive,-300,0,1650,1100);ctx.restore()}
 for(let x=48;x<w;x+=48)line(x,0,x,h,'#8796bf14');for(let y=48;y<h;y+=48)line(0,y,w,y,'#8796bf14');
 const n=Math.round(design.energy*.30)+5;for(let i=0;i<n;i++){let x=rand()*w,y=120+rand()*(h-220),r=2+rand()*4;ctx.fillStyle=[p.a+'80',p.b+'70',p.c+'88'][i%3];ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();if(i%4===0){line(x-8,y,x+8,y,p.a+'40');line(x,y-8,x,y+8,p.a+'40')}}
 ctx.save();ctx.globalCompositeOperation='lighten';ctx.globalAlpha=.55+design.energy*.003;ctx.filter=design.palette==='fire'?'sepia(.85) saturate(1.9) hue-rotate(-18deg)':design.palette==='violet'?'hue-rotate(34deg) saturate(.95)':'none';const src={sculpture:'fusion-master.webp',gesture:'fusion-expression.webp',orbit:'fusion-matter.webp'}[design.composition],im=images[src];if(im)ctx.drawImage(im,-210,150,1320,880);ctx.restore();
 ctx.save();ctx.strokeStyle=p.a+'66';ctx.lineWidth=2;ctx.setLineDash([4,12]);if(design.composition==='orbit'){for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse(460,550,310-i*45,370-i*55,-.35+i*.2,0,Math.PI*2);ctx.strokeStyle=[p.a+'88',p.b+'88',p.c+'66',p.a+'44'][i];ctx.stroke()}}else{ctx.strokeRect(43,110,w-86,h-220)}ctx.restore();
 if(design.composition==='gesture'){ctx.save();ctx.strokeStyle=p.b;ctx.lineWidth=20;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-40,660);ctx.bezierCurveTo(500,880,130,120,880,380);ctx.globalAlpha=.65;ctx.stroke();ctx.restore()}else if(design.composition==='sculpture'){ctx.save();ctx.globalAlpha=.7;let g=ctx.createLinearGradient(0,730,700,1100);g.addColorStop(0,p.a);g.addColorStop(.49,p.a);g.addColorStop(.5,p.b);g.addColorStop(1,p.b);ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(-90,1100);ctx.lineTo(200,720);ctx.lineTo(670,1100);ctx.closePath();ctx.fill();ctx.restore()}
 smallText('AQUÍ DISEÑAMOS / ESTUDIO CREATIVO',48,56,p.a,13);smallText('AD—'+String(design.seed%1000).padStart(3,'0'),w-48,56,p.c,13,'right');line(48,78,w-48,78,'#bdc8e34d');smallText('LA IMAGINACIÓN TOMA FORMA.',48,117,'#a8b7d0',11);
 let word=design.word.trim().toLocaleUpperCase('es')||'IMAGINÁ';let size=fitWord(word,770,174);ctx.save();ctx.textAlign='center';ctx.textBaseline='alphabetic';let y=design.composition==='orbit'?600:790;if(design.composition==='gesture'){ctx.translate(450,y);ctx.rotate(-.1);ctx.translate(-450,-y)}ctx.font='700 '+size+'px Display, sans-serif';for(let i=8;i>0;i--){ctx.fillStyle=i>4?p.b:'#143747';ctx.fillText(word,450+i,y+i)}ctx.strokeStyle='#07101d';ctx.lineWidth=4;ctx.strokeText(word,450,y);ctx.fillStyle='#f6f1ed';ctx.fillText(word,450,y);ctx.restore();
 spark(design.spark.x*w,design.spark.y*h,45+design.energy*.2,p.c);smallText('DEL PLANO',48,h-88,'#ecedf3',14);smallText('A LO EXTRAORDINARIO.',48,h-62,p.a,14);smallText('↗',w-50,h-60,p.c,46,'right');line(48,h-127,w-48,h-127,'#bdc8e333');smallText('COLOR / '+p.name.toUpperCase()+'    COMPOSICIÓN / '+({sculpture:'VOLUMEN',gesture:'GESTO',orbit:'ÓRBITA'}[design.composition]),48,h-150,'#8c9ab6',10);canvas.setAttribute('aria-label','Exploración gráfica de «'+word+'», paleta '+p.name+', composición '+({sculpture:'Volumen',gesture:'Gesto',orbit:'Órbita'}[design.composition])+'. Arrastrá la chispa o usá las flechas del teclado para moverla.');}
function readWord(){design.word=$('#design-word').value;draw()}
$('#design-word').addEventListener('input',readWord);
$$('button[data-palette]').forEach(b=>b.addEventListener('click',()=>{design.palette=b.dataset.palette;$$('button[data-palette]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});draw();$('#design-status').textContent='Paleta '+palettes[design.palette].name+'. Tu composición sigue abierta a nuevas ideas.'}));
$$('button[data-composition]').forEach(b=>b.addEventListener('click',()=>{design.composition=b.dataset.composition;$$('button[data-composition]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});draw();$('#design-status').textContent='Composición actualizada. Arrastrá la chispa para darle tu propio balance.'}));
$('#design-energy').addEventListener('input',e=>{design.energy=Number(e.target.value);$('#energy-value').textContent=design.energy+'%';draw()});
$('#remix').addEventListener('click',()=>{design.seed+=17;const r=rng(design.seed);design.spark={x:.2+r()*.6,y:.2+r()*.45};draw();$('#design-status').textContent='Nueva mezcla creada. Conservamos tu palabra y tu paleta; exploramos otro balance.'});
let dragging=false;function moveSpark(event){const r=canvas.getBoundingClientRect();design.spark={x:Math.min(.92,Math.max(.08,(event.clientX-r.left)/r.width)),y:Math.min(.88,Math.max(.12,(event.clientY-r.top)/r.height))};draw()}
canvas.addEventListener('pointerdown',event=>{dragging=true;canvas.setPointerCapture(event.pointerId);moveSpark(event)});canvas.addEventListener('pointermove',event=>{if(dragging)moveSpark(event)});canvas.addEventListener('pointerup',event=>{dragging=false;if(canvas.hasPointerCapture(event.pointerId))canvas.releasePointerCapture(event.pointerId);$('#design-status').textContent='El balance ahora es tuyo. Podés seguir explorando o descargar tu pieza.'});canvas.addEventListener('pointercancel',()=>dragging=false);
canvas.addEventListener('keydown',e=>{const delta={ArrowLeft:[-.025,0],ArrowRight:[.025,0],ArrowUp:[0,-.025],ArrowDown:[0,.025]}[e.key];if(!delta)return;e.preventDefault();design.spark.x=Math.max(.08,Math.min(.92,design.spark.x+delta[0]));design.spark.y=Math.max(.12,Math.min(.88,design.spark.y+delta[1]));draw()});
$('#download-art').addEventListener('click',()=>{draw();canvas.toBlob(blob=>{if(!blob){$('#design-status').textContent='No se pudo crear la descarga. Volvé a intentarlo.';return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mi-exploracion-aqui-disenamos.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1200);$('#design-status').textContent='Descarga PNG solicitada. Tu exploración se preparó en este dispositivo.'},'image/png')});
$('#use-design').addEventListener('click',()=>{const comp={sculpture:'volumen',gesture:'gesto',orbit:'órbita'}[design.composition];const text='Quiero desarrollar la idea «'+(design.word.trim()||'IMAGINÁ')+'», con la paleta '+palettes[design.palette].name+', una composición de '+comp+' y una intensidad gráfica del '+design.energy+'%.';$('#idea').value=$('#idea').value?$('#idea').value+'\n\n'+text:text;$('#service').value='Identidad de marca';clearBrief()});
$('#download-art').disabled=true;draw();Promise.all([Promise.all(imageLoads),document.fonts.ready]).then(()=>{draw();$('#download-art').disabled=false});
let preparedBrief='';function clearBrief(){preparedBrief='';$('#brief-actions').hidden=true;$('#form-status').textContent=''}
$('#brief-form').addEventListener('input',clearBrief);$('#brief-form').addEventListener('change',clearBrief);$('#brief-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);preparedBrief=`MI IDEA — AQUÍ DISEÑAMOS\nDel plano a lo extraordinario.\n\nNombre: ${d.get('nombre')}\nCorreo: ${d.get('correo')}\nServicio: ${d.get('servicio')}\n\nMi idea:\n${d.get('idea')}\n\nResumen preparado localmente. No se ha enviado al estudio.\n`;$('#form-status').textContent='Tu brief está listo para descargar. Todavía no se ha enviado al estudio.';$('#brief-actions').hidden=false});$('#download-brief').addEventListener('click',()=>{if(!preparedBrief)return;const url=URL.createObjectURL(new Blob([preparedBrief],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='mi-idea-aqui-disenamos.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#form-status').textContent='Descarga solicitada. Tu brief no se ha enviado al estudio.'});
let scrollFrame=0;function progress(){const d=document.documentElement;$('.scroll-progress').style.transform='scaleX('+d.scrollTop/Math.max(1,d.scrollHeight-d.clientHeight)+')';scrollFrame=0}addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(progress)},{passive:true});progress();$('#year').textContent=new Date().getFullYear();
